'use strict';

// 解包（open）：固定顺序 文件限长 → JSON → 信封 Schema → 验签 → GCM 认证解密 → 负载 Schema。
// 任一步失败不返回部分明文。

const crypto = require('node:crypto');
const { canonicalizeJson } = require('./canonical-json.cjs');
const { validateEnvelopeSchema, validatePayloadSchema } = require('./schema.cjs');
const { MAX_PACKAGE_BYTES, AES_KEY_BYTES, ED25519_PUBLIC_KEY_BYTES, BASE64_PATTERN } = require('./constants.cjs');

function openError(code, message) {
  const error = new Error(message);
  error.code = code;
  error.status = 400;
  return error;
}

function normalizeAesKey(aesKey) {
  let key;
  if (Buffer.isBuffer(aesKey)) key = aesKey;
  else if (typeof aesKey === 'string' && BASE64_PATTERN.test(aesKey)) key = Buffer.from(aesKey, 'base64');
  else throw openError('OPEN_KEY_INVALID', 'AES 密钥无效');
  if (key.length !== AES_KEY_BYTES) throw openError('OPEN_KEY_INVALID', 'AES 密钥必须是 32 字节');
  return key;
}

// 导入客户内置验签公钥（DER SPKI base64），验证为 Ed25519 且 SPKI 公钥材料 32 字节。
function importVerifyKey(publicKey) {
  let key;
  try {
    const der = Buffer.isBuffer(publicKey) ? publicKey : Buffer.from(publicKey, 'base64');
    key = crypto.createPublicKey({ key: der, format: 'der', type: 'spki' });
  } catch (_) {
    throw openError('OPEN_VERIFY_KEY_INVALID', '验签公钥无效');
  }
  if (key.asymmetricKeyType !== 'ed25519') {
    throw openError('OPEN_VERIFY_KEY_INVALID', '验签公钥必须是 Ed25519');
  }
  const raw = key.export({ format: 'der', type: 'spki' });
  // Ed25519 SPKI DER：前 12 字节为固定头部，其后 32 字节为原始公钥材料。
  if (raw.length !== 12 + ED25519_PUBLIC_KEY_BYTES) {
    throw openError('OPEN_VERIFY_KEY_INVALID', '验签公钥材料长度无效');
  }
  return key;
}

// 从公开信封移除 signature 成员，用于构造签名输入对象。
function envelopeForSigning(envelope) {
  const { signature, ...rest } = envelope;
  return rest;
}

function open(envelopeText, { aesKey, verifyPublicKey, allowedHosts = null } = {}) {
  // 1. 文件限长
  if (typeof envelopeText !== 'string') {
    throw openError('PACKAGE_INVALID', 'Key 包必须是字符串');
  }
  const bytes = Buffer.byteLength(envelopeText, 'utf8');
  if (bytes > MAX_PACKAGE_BYTES) {
    throw openError('PACKAGE_TOO_LARGE', 'Key 包超过大小限制');
  }

  // 2. JSON 解析
  let envelope;
  try {
    envelope = JSON.parse(envelopeText);
  } catch (_) {
    throw openError('PACKAGE_INVALID_JSON', 'Key 包不是合法 JSON');
  }

  // 3. 信封 Schema
  validateEnvelopeSchema(envelope);

  // 4. 验签（先验签，后解密）
  const verifyKey = importVerifyKey(verifyPublicKey);
  const signingInput = Buffer.from(canonicalizeJson(envelopeForSigning(envelope)), 'utf8');
  const signature = Buffer.from(envelope.signature.value, 'base64');
  const valid = crypto.verify(null, signingInput, verifyKey, signature);
  if (!valid) {
    throw openError('PACKAGE_SIGNATURE_INVALID', 'Key 包签名校验失败');
  }

  // 5. GCM 认证解密
  const key = normalizeAesKey(aesKey);
  const iv = Buffer.from(envelope.cipher.iv, 'base64');
  const authTag = Buffer.from(envelope.cipher.authTag, 'base64');
  const ciphertext = Buffer.from(envelope.ciphertext, 'base64');
  let plaintext;
  try {
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(authTag);
    plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  } catch (_) {
    throw openError('PACKAGE_DECRYPT_FAILED', 'Key 包解密失败');
  }

  // 6. 负载 Schema
  let payload;
  try {
    payload = JSON.parse(plaintext.toString('utf8'));
  } catch (_) {
    throw openError('PACKAGE_PAYLOAD_INVALID', 'Key 包负载无效');
  }
  validatePayloadSchema(payload, allowedHosts);

  return payload;
}

module.exports = { open, importVerifyKey, normalizeAesKey };
